// Called for every inference frame from the 'model' node.
// 1) remember the newest boxes for /api/track  2) push the JPEG to every open /api/stream.mjpg client
const data = msg.payload && msg.payload.data || {};
const labels = Array.isArray(data.labels) ? data.labels.map(String) : [];
const boxes = Array.isArray(data.boxes) ? data.boxes : [];
const res = Array.isArray(data.resolution) ? data.resolution : [640, 640];
const WATCH = ['elephant','bear','person','truck','car','bus','motorcycle','cow','dog','horse','sheep','bird'];
let best = null;
for (let i = 0; i < labels.length; i++) {
  const l = labels[i].toLowerCase(); if (!WATCH.includes(l)) continue;
  const b = boxes[i] || []; let sc = Number(b[4] ?? 0.8); if (sc > 1) sc /= 100;
  if (!best || WATCH.indexOf(l) < WATCH.indexOf(best.type)) best = { type: l, confidence: Math.round(sc*100)/100, box: [b[0]/res[0], b[1]/res[1], (b[2]||0)/res[0], (b[3]||0)/res[1]] };
}
flow.set('kvTrack', { ts: Date.now(), labels, res, best });

if (data.image) {
  const buf = Buffer.from(String(data.image).replace(/^data:image\/\w+;base64,/, ''), 'base64');
  const clients = global.get('kvMjpegClients') || [];
  const alive = [];
  for (const r of clients) {
    try {
      if (!r.writableEnded && !r.destroyed) {
        r.write(`--frame\r\nContent-Type: image/jpeg\r\nContent-Length: ${buf.length}\r\n\r\n`);
        r.write(buf); r.write('\r\n'); alive.push(r);
      }
    } catch (e) {}
  }
  global.set('kvMjpegClients', alive);
  node.status({ fill: 'green', shape: 'dot', text: `${alive.length} viewer(s) · ${best ? best.type : 'clear'}` });
}
return null;

// Keep the HTTP response open and register it; 'live frame' writes the JPEGs.
const r = msg.res._res;
r.writeHead(200, {
  'Content-Type': 'multipart/x-mixed-replace; boundary=frame',
  'Cache-Control': 'no-cache, no-store',
  'Connection': 'close',
  'Pragma': 'no-cache',
  'Access-Control-Allow-Origin': '*'
});
const clients = global.get('kvMjpegClients') || [];
clients.push(r);
global.set('kvMjpegClients', clients);
r.on('close', () => { global.set('kvMjpegClients', (global.get('kvMjpegClients') || []).filter(x => x !== r)); });
return null;

msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', 'Access-Control-Allow-Origin': '*' };
const t = flow.get('kvTrack') || { ts: 0, labels: [], best: null };
const st = flow.get('kv') || { pan: 90, tilt: 90, tracking: false };
msg.payload = { ts: t.ts, age_ms: Date.now() - t.ts, labels: t.labels, res: t.res || null, best: t.best, pan: st.pan, tilt: st.tilt, tracking: !!st.tracking, id: env.get('KV_ID') || 'KDN-01' };
return msg;
